/* @autogenerated */
import { Component, signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of } from 'rxjs';
import { Acl } from '@shared/data/acl/acl.model';
import { ConfirmDialogService } from '../dialog/confirm-dialog.service';
import { LongTaskService } from '../long-task-view/long-task.service';
import { NotifyService } from '../notify/notify.service';
import { ConfirmSelectionAction } from './confirm-selection-action';

interface Item {
  uid: string;
}

const acl = signal<{ generic: Acl } | undefined>(undefined);
const repository = {
  acl: () => Object.assign(acl, { fetch: jasmine.createSpy('fetch') }) as any,
  canDeleteSelection: jasmine.createSpy('canDeleteSelection'),
  deleteSelection: jasmine.createSpy('deleteSelection'),
};

@Component({ selector: 'test-delete-selection-action', template: '' })
class TestDeleteSelectionAction extends ConfirmSelectionAction<Item> {
  readonly name = 'deleteSelection';
  protected readonly scope = 'test';
  protected readonly repository = repository;

  protected runSelection(items: Item[]) {
    return this.repository.deleteSelection({ uids: items.map((item) => item.uid) });
  }
}

describe('ConfirmSelectionAction', () => {
  let longTask: jasmine.SpyObj<LongTaskService>;
  let confirm: jasmine.SpyObj<ConfirmDialogService>;
  let action: TestDeleteSelectionAction;

  beforeEach(() => {
    acl.set({ generic: { allows: [{ name: 'delete', allowed: true }] } });
    repository.canDeleteSelection.and.returnValue(true);
    longTask = jasmine.createSpyObj<LongTaskService>('LongTaskService', ['run']);
    confirm = jasmine.createSpyObj<ConfirmDialogService>('ConfirmDialogService', ['confirm']);
    TestBed.configureTestingModule({
      imports: [
        TestDeleteSelectionAction,
        TranslocoTestingModule.forRoot({
          langs: { en: {}, 'test/en': { action: { 'delete-selection': { progress: 'Deleting…' } } } },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
        }),
      ],
      providers: [
        { provide: LongTaskService, useValue: longTask },
        { provide: ConfirmDialogService, useValue: confirm },
        { provide: NotifyService, useValue: jasmine.createSpyObj('NotifyService', ['success']) },
      ],
    });
    const fixture = TestBed.createComponent(TestDeleteSelectionAction);
    fixture.detectChanges();
    action = fixture.componentInstance;
  });

  afterEach(() => TestBed.resetTestingModule());

  it('uses the permission without the Selection suffix', () => {
    expect(action.multiple).toBeTrue();
    expect(action.visible([])()).toBeTrue();
  });

  it('is hidden when the repository does not support bulk operations', () => {
    repository.canDeleteSelection.and.returnValue(false);
    acl.set({ generic: { allows: [{ name: 'delete', allowed: true }] } });
    expect(action.visible([])()).toBeFalse();
  });

  it('follows the task, clears the selection and closes the container', () => {
    const progress = of({} as any);
    repository.deleteSelection.and.returnValue(progress);
    confirm.confirm.and.returnValue(of(true));
    longTask.run.and.returnValue(of(undefined));
    const container = { close: jasmine.createSpy('close'), selectionModel: { clearSelection: jasmine.createSpy() } };
    action.container.set(container as any);
    action.selection = signal([{ uid: 'a' }, { uid: 'b' }]);

    action.run();

    expect(repository.deleteSelection).toHaveBeenCalledWith({ uids: ['a', 'b'] });
    expect(longTask.run).toHaveBeenCalledWith('Deleting…', progress);
    expect(container.selectionModel.clearSelection).toHaveBeenCalled();
    expect(container.close).toHaveBeenCalled();
  });
});
